\title{Negative-Dimensional Cellular Topology:\\Euler Parity, Pro-Towers, and Stabilization}
\author{Aristotle}
\date{July 19, 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a finite cellular model in which formal dimension ranges over all integers. A virtual cellular object is a finitely supported integer-valued multiplicity function on $\Z$, and its extended Euler characteristic is evaluation against the parity character $d\mapsto(-1)^d$. For pure objects concentrated in one degree, this gives the exact formula $\chi(X)=(-1)^dc$, where $c$ is the finite component multiplicity. In particular, a pure object of dimension $-n$ satisfies $\chi(X)=(-1)^n|\pi_0(X)|$. We define suspension as translation by one degree and prove that one suspension reverses Euler characteristic, while $k$ suspensions multiply it by $(-1)^k$. The $2n$-fold suspension reflects dimension $-n$ to dimension $n$ while preserving Euler characteristic and component count. Component-preserving negative-dimensional pro-spectra exhibit exact alternation $\chi_k=(-1)^k\chi_0$. Stagewise stabilization preserves both invariants. Finally, equivariant maps of antipodal spheres persist under simultaneous suspension while the pro-Euler invariant records the parity of the same shift. Purity is essential, since mixed-degree contributions can cancel.
\end{abstract}

\section{Introduction}

Ordinary finite cell complexes use dimensions $0,1,2,\ldots$, and their Euler characteristic is an alternating sum of cell counts. Stable topology changes the role of dimension: suspension shifts all degrees, desuspension shifts them oppositely, and stable objects naturally carry integer gradings. Negative dimension here is not a locally Euclidean space with a negative number of coordinates. It is a formal topological degree in a translation-invariant theory.

The elementary identity
\[
(-1)^{d+e}=(-1)^d(-1)^e
\]
for $d,e\in\Z$ is the foundation. Parity is a multiplicative character of the additive dimension group. Evaluating finite integer-graded cellular data against it extends the Euler sum across degree zero.

We establish five main conclusions: pure objects satisfy an exact signed component formula; iterated suspension acts by a parity sign; reflection from degree $-n$ to $n$ is Euler-neutral; component-preserving negative pro-towers alternate with period two; and the same additive translation raises both dimensions in antipodal suspension towers while preserving their difference. The restriction to purity is indispensable because mixed adjacent degrees may cancel.

\section{Integer-graded virtual cellular data}

\begin{definition}[Virtual cellular space]
A finite integer-graded virtual cellular space is a function $a:\Z\to\Z$ with finite support. Its value $a_d$ is the virtual multiplicity in degree $d$. Addition is pointwise. Writing $[d]$ for the basis element concentrated in degree $d$, every such space has a unique finite expression
\[
a=\sum_{d\in\Z}a_d[d].
\]
\end{definition}

\begin{definition}[Parity character and Euler characteristic]
The parity character is $\varepsilon(d)=(-1)^d$. It obeys $\varepsilon(d+e)=\varepsilon(d)\varepsilon(e)$. The extended Euler characteristic is
\[
\chi(a)=\sum_{d\in\Z}(-1)^da_d.
\]
The sum is finite and additive in $a$.
\end{definition}

Negative powers are harmless because $-1$ is a unit equal to its own inverse.

\begin{lemma}[Single-degree evaluation]
If $a=c[d]$ is supported only in degree $d$, then
\[
\chi(a)=(-1)^dc.
\]
\end{lemma}
\begin{proof}
All terms in the Euler sum vanish except the term indexed by $d$.
\end{proof}

\begin{definition}[Pure finite cellular object]
A pure finite cellular object is a pair $X=(d,c)$ with $d\in\Z$ and $c\in\N$. We set
\[
\dim(X)=d,\qquad |\pi_0(X)|=c,
\]
and realize $X$ as $c[d]$. Thus $c$ is interpreted as a finite component count.
\end{definition}

\begin{theorem}[Pure Euler formula]
Every pure finite cellular object satisfies
\[
\chi(X)=(-1)^{\dim(X)}|\pi_0(X)|.
\]
\end{theorem}
\begin{proof}
Apply single-degree evaluation to the realization $c[d]$.
\end{proof}

For $n,c\in\N$, write $N(n,c)=(-n,c)$ and $P(n,c)=(n,c)$.

\begin{corollary}[Negative-dimensional Euler law]
A pure object of dimension $-n$ and component count $c$ satisfies
\[
\chi(N(n,c))=(-1)^n|\pi_0(N(n,c))|=(-1)^nc.
\]
\end{corollary}
\begin{proof}
The pure formula gives $(-1)^{-n}c$. Since $-1$ is its own inverse, $(-1)^{-n}=(-1)^n$.
\end{proof}

\begin{remark}[Necessity of purity]
The mixed object $[-1]+[-2]$ has total positive multiplicity $2$ but Euler characteristic $-1+1=0$. A mixed object has no single degree whose parity can be factored out. Thus the signed component formula is a theorem about concentration in one degree, not arbitrary graded data.
\end{remark}

\section{Suspension and reflection stabilization}

\begin{definition}[Suspension]
For $X=(d,c)$ define $\Sigma X=(d+1,c)$. Recursively, $\Sigma^0X=X$ and $\Sigma^{k+1}X=\Sigma(\Sigma^kX)$.
\end{definition}

\begin{theorem}[One-step suspension law]
For every pure object $X$,
\[
\chi(\Sigma X)=-\chi(X).
\]
\end{theorem}
\begin{proof}
If $X=(d,c)$, then $\chi(\Sigma X)=(-1)^{d+1}c=-(-1)^dc=-\chi(X)$.
\end{proof}

\begin{theorem}[Iterated suspension data]
For $k\in\N$,
\[
\dim(\Sigma^kX)=\dim(X)+k,
\qquad
|\pi_0(\Sigma^kX)|=|\pi_0(X)|.
\]
\end{theorem}
\begin{proof}
Induct on $k$. The zeroth step is immediate. Each successor step adds one to dimension and preserves the component count.
\end{proof}

\begin{theorem}[Iterated Euler suspension law]
For every $k\in\N$,
\[
\chi(\Sigma^kX)=(-1)^k\chi(X).
\]
\end{theorem}
\begin{proof}
Induct on $k$. At the successor step, the one-step law changes the preceding value by a factor of $-1$.
\end{proof}

\begin{definition}[Reflection stabilization]
For $n,c\in\N$, define
\[
\Stab(n,c)=\Sigma^{2n}N(n,c).
\]
\end{definition}

\begin{theorem}[Stabilization data]
Reflection stabilization satisfies
\[
\dim(\Stab(n,c))=n,
\qquad
|\pi_0(\Stab(n,c))|=c.
\]
\end{theorem}
\begin{proof}
The new dimension is $-n+2n=n$, and suspension preserves component count.
\end{proof}

\begin{theorem}[Euler-neutral stabilization]
For every $n,c\in\N$,
\[
\chi(\Stab(n,c))=\chi(N(n,c)).
\]
\end{theorem}
\begin{proof}
Iterated suspension multiplies the Euler value by $(-1)^{2n}=1$.
\end{proof}

The result separates displacement from parity response: reflection traverses $2n$ degrees, so it is invisible to the parity character.

\section{Negative-dimensional pro-spectra}

\begin{definition}[Component-preserving negative pro-spectrum]
Such a pro-spectrum consists of a base depth $b\in\N$, component counts $c_k\in\N$, and bonding data satisfying $c_{k+1}=c_k$ for every $k$. Its $k$th stage is
\[
X_k=N(b+k,c_k)=(-(b+k),c_k).
\]
\end{definition}

\begin{lemma}[Constancy of components]
For every $k\in\N$, one has $c_k=c_0$.
\end{lemma}
\begin{proof}
Induction on $k$: the bonding equality carries the induction hypothesis from $k$ to $k+1$.
\end{proof}

\begin{theorem}[Pro-Euler alternation]
For a component-preserving negative-dimensional pro-spectrum,
\[
\chi(X_k)=(-1)^k\chi(X_0)
\]
for every $k\in\N$.
\end{theorem}
\begin{proof}
The negative-dimensional law and component constancy give
\[
\chi(X_k)=(-1)^{b+k}c_0=(-1)^k((-1)^bc_0)=(-1)^k\chi(X_0).
\]
\end{proof}

Thus $(-1)^k\chi(X_k)$ is constant. The Euler sequence has exact period two when $c_0\ne0$ and is identically zero when $c_0=0$.

\begin{definition}[Stagewise stabilization]
Define
\[
Y_k=\Stab(b+k,c_k)=\Sigma^{2(b+k)}X_k.
\]
Then $Y_k$ lies in positive dimension $b+k$.
\end{definition}

\begin{theorem}[Stagewise stabilization invariants]
For every $k$,
\[
\chi(Y_k)=\chi(X_k),
\qquad
|\pi_0(Y_k)|=|\pi_0(X_k)|.
\]
\end{theorem}
\begin{proof}
Apply Euler-neutral stabilization and stabilization data with $n=b+k$ and $c=c_k$.
\end{proof}

\section{Antipodal suspension and the translation bridge}

Equip $S^r$ with the antipodal involution $x\mapsto-x$. An antipodal map $f:S^m\to S^n$ satisfies $f(-x)=-f(x)$. Suspension preserves this equivariance.

\begin{theorem}[Antipodal suspension tower]
If an antipodal map $S^m\to S^n$ exists, then for every $k\in\N$ an antipodal map
\[
S^{m+k}\longrightarrow S^{n+k}
\]
exists.
\end{theorem}
\begin{proof}
Equivariant suspension raises source and target dimensions by one and preserves the antipodal relation. Iterate by induction on $k$.
\end{proof}

In particular, the dimension excess remains fixed:
\[
(n+k)-(m+k)=n-m.
\]

\begin{theorem}[Stabilization--coindex bridge]
Let $(X_k)$ be a component-preserving negative-dimensional pro-spectrum. If an antipodal map $S^m\to S^n$ exists, then for every $k\in\N$ an antipodal map $S^{m+k}\to S^{n+k}$ exists and
\[
\chi(X_k)=(-1)^k\chi(X_0).
\]
\end{theorem}
\begin{proof}
The first assertion is the antipodal suspension theorem, and the second is pro-Euler alternation. Both are governed by the same additive translation $k$: index differences ignore simultaneous translation, while Euler data evaluate it through parity.
\end{proof}

This bridge identifies a common mechanism, not an identification of the underlying objects.

\section{Algorithms and numerical realization}

For finitely supported data, Euler evaluation scans its $r$ nonzero entries and accumulates $a_d$ with a plus sign for even $d$ and a minus sign for odd $d$. It runs in $O(r)$ time and $O(1)$ auxiliary space. Pure evaluation is constant time.

The $k$-fold suspension is computed directly as
\[
(d,c)\longmapsto(d+k,c),
\]
with Euler multiplier $(-1)^k$. Reflection stabilization maps $(-n,c)$ to $(n,c)$ and preserves its Euler value, again in constant time in a unit-cost arithmetic model.

For a tower with base $b$, constant component count $c$, and finite horizon $L$, generate
\[
X_k=(-(b+k),c),\qquad \chi_k=(-1)^{b+k}c,
\quad 0\le k<L.
\]
This requires $O(L)$ time and output space, or constant working space when streamed. The identity $(-1)^k\chi_k=\chi_0$ provides a stagewise diagnostic.

\section{Applications and limitations}

Integer gradings and shifts occur throughout chain complexes, spectra, and derived constructions. The parity character is the simplest numerical trace of such a grading. In a purported component-preserving pure tower, failure of corrected Euler constancy detects either changing components or loss of purity.

For pure stages, degree parity and component count determine Euler characteristic completely. Mixed data expose the limitation: Euler characteristic forgets internal cancellation. Distinct graded ledgers can share the same Euler value, so the invariant cannot reconstruct a mixed object.

The antipodal example suggests an equivariant extension. For finite group actions, invariants valued in a representation ring may retain information discarded by an integer. Suspension by a real representation should involve its determinant character. Ordinary parity then arises from a one-dimensional sign representation.

\section{Future directions}

A first direction is to allow derived pro-spectra with nonconstant bonding homology. Eventual period-two Euler behavior may characterize an eventual pure translate of a fixed virtual homology class when perfectness excludes invisible Euler-neutral summands.

A second direction is a universal property: any additive integer-valued invariant that counts degree-zero generators and reverses sign under suspension should equal parity-character Euler evaluation in every integer degree.

A third direction weakens exact preservation to congruence. If component counts stabilize modulo $q$, parity-corrected Euler values should stabilize modulo $q$; suitable converse statements may follow from stabilization modulo prime powers.

A fourth direction replaces scalar parity by equivariant determinant characters. For a finite group $G$ and real $G$-representation $V$, suspension by $V$ should multiply a representation-ring-valued Euler characteristic by the determinant character of $V$.

\section{Conclusion}

Evaluation against the parity character extends finite cellular Euler data across all integer degrees. A pure object in dimension $-n$ satisfies
\[
\chi(X)=(-1)^n|\pi_0(X)|.
\]
Suspension translates degree and contributes one sign per step; the even reflection from $-n$ to $n$ preserves Euler characteristic and components. Component-preserving negative pro-spectra alternate exactly, and stagewise reflection transports them to positive degrees without changing their basic invariants. Antipodal suspension towers exhibit the same additive shift through preservation of a dimension difference. Negative dimension is therefore a precise address for graded information controlled by translation, parity, and purity.

\end{document}

