from typing import List

def signed_component_row(components: int, max_depth: int) -> List[int]:
    if components < 0 or max_depth < 0:
        raise ValueError("inputs must be nonnegative")
    return [components if depth % 2 == 0 else -components
            for depth in range(max_depth + 1)]

if __name__ == "__main__":
    for c in range(1, 5):
        print(c, signed_component_row(c, 4))

from typing import Tuple

def stabilize(depth: int, components: int) -> Tuple[int, int, int]:
    if depth < 0 or components < 0:
        raise ValueError("inputs must be nonnegative")
    source_euler = components if depth % 2 == 0 else -components
    target_dimension = -depth + 2 * depth
    target_euler = components if target_dimension % 2 == 0 else -components
    assert source_euler == target_euler
    return target_dimension, components, target_euler

if __name__ == "__main__":
    for n, c in [(1, 3), (2, 5), (5, 2)]:
        print(n, c, stabilize(n, c))

