from typing import Mapping

def extended_euler(data: Mapping[int, int]) -> int:
    """Evaluate finite graded multiplicities against the parity character."""
    return sum(value if degree % 2 == 0 else -value
               for degree, value in data.items())

from dataclasses import dataclass

@dataclass(frozen=True)
class PureObject:
    dimension: int
    components: int

    @property
    def euler(self) -> int:
        return self.components if self.dimension % 2 == 0 else -self.components

def reflection_stabilize(depth: int, components: int) -> PureObject:
    if depth < 0 or components < 0:
        raise ValueError("inputs must be nonnegative")
    source = PureObject(-depth, components)
    target = PureObject(source.dimension + 2 * depth, components)
    assert target.euler == source.euler
    return target

from typing import Iterator, Tuple

def stream_negative_tower(base: int, components: int, stages: int) -> Iterator[Tuple[int, int, int]]:
    """Yield (stage, dimension, Euler value) without storing the tower."""
    if min(base, components, stages) < 0:
        raise ValueError("inputs must be nonnegative")
    for k in range(stages):
        dimension = -(base + k)
        euler = components if dimension % 2 == 0 else -components
        yield k, dimension, euler

